type Presentation = {
  id: string; playerId: string; agentName: string; agency: string; submittedAt: string; fitReason: string;
  requestedAction: string; status: 'New' | 'Reviewing' | 'Shortlisted' | 'Info requested';
};
type Conversation = { id: string; agentName: string; agency: string; playerName: string; lastMessage: string; timestamp: string; unread: boolean; messages: { from: 'club' | 'agent'; text: string; time: string }[] };
type ActivityItem = { id: string; type: string; title: string; description: string; timestamp: string };

