type PortalContextType = {
  needs: RecruitmentNeed[]; setNeeds: React.Dispatch<React.SetStateAction<RecruitmentNeed[]>>;
  players: Player[]; setPlayers: React.Dispatch<React.SetStateAction<Player[]>>;
  presentations: Presentation[]; setPresentations: React.Dispatch<React.SetStateAction<Presentation[]>>;
  conversations: Conversation[]; setConversations: React.Dispatch<React.SetStateAction<Conversation[]>>;
  activities: ActivityItem[]; clubProfile: Club;
};
const PortalContext = createContext<PortalContextType | null>(null);
function usePortal() {
  const value = useContext(PortalContext);
  if (!value) throw new Error('Portal context missing');
  return value;
}
function PortalProvider({ children }: { children: ReactNode }) {
  const [needs, setNeeds] = useState(seedNeeds);
  const [players, setPlayers] = useState(seedPlayers);
  const [presentations, setPresentations] = useState(seedPresentations);
  const [conversations, setConversations] = useState(seedConversations);
  return <PortalContext.Provider value={{ needs, setNeeds, players, setPlayers, presentations, setPresentations, conversations, setConversations, activities: seedActivities, clubProfile: club }}>{children}</PortalContext.Provider>;
}

