function KpiCard({ label, value, detail, icon: Icon, tone = 'green' }: { label: string; value: string; detail: string; icon: typeof Target; tone?: 'green' | 'orange' | 'navy' }) {
  return <div className="relative overflow-hidden rounded-xl border border-card-border bg-card p-5 shadow-[0_4px_20px_rgba(34,41,53,.035)]"><div className={`absolute right-0 top-0 h-1 w-20 ${tone === 'orange' ? 'bg-accent' : tone === 'navy' ? 'bg-[#364b72]' : 'bg-primary'}`} /><div className="flex items-start justify-between"><div><p className="font-mono-data text-[10px] uppercase tracking-[.14em] text-muted-foreground">{label}</p><p className="mt-3 font-display text-3xl font-bold tracking-[-.05em]">{value}</p></div><div className={`grid size-9 place-items-center rounded-lg ${tone === 'orange' ? 'bg-accent/10 text-accent' : tone === 'navy' ? 'bg-[#364b72]/10 text-[#364b72]' : 'bg-primary/10 text-primary'}`}><Icon size={18} /></div></div><p className="mt-3 flex items-center gap-1 text-[11px] text-muted-foreground"><ArrowDownRight size={13} className="text-primary" />{detail}</p></div>;
}

function StatusPill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'orange' | 'red' | 'blue' }) {
  const colors = { neutral: 'bg-muted text-muted-foreground', green: 'bg-primary/10 text-primary', orange: 'bg-accent/12 text-accent', red: 'bg-destructive/10 text-destructive', blue: 'bg-[#364b72]/10 text-[#364b72]' };
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 font-mono-data text-[10px] font-medium ${colors[tone]}`}><span className="size-1.5 rounded-full bg-current opacity-70" />{children}</span>;
}

